"use client";

/**
 * Original design by Gustavo Fior (@gustavo-fior) and Foglamp Labs,
 * co-founded by Abdul Haidar. Extracted AS-IS from foglamp-labs/foglamp.
 */

import * as React from "react";

type FoglampLinkComponent = React.ElementType;

const FoglampLinkContext = React.createContext<FoglampLinkComponent>("a");

export type FoglampLinkProviderProps = {
	/** Router or link component that should render every FoglampLink below it. */
	component: FoglampLinkComponent;
	children: React.ReactNode;
};

export function FoglampLinkProvider({
	component,
	children,
}: FoglampLinkProviderProps) {
	return (
		<FoglampLinkContext.Provider value={component}>
			{children}
		</FoglampLinkContext.Provider>
	);
}

/**
 * A link with no wrapper of its own. The provider component receives the
 * original props directly, so the rendered DOM and styling stay with the
 * router's link implementation. A per-link component or `as` can override it.
 */
export type FoglampLinkProps<Component extends FoglampLinkComponent = "a"> =
	React.ComponentPropsWithRef<Component> & {
		component?: Component;
		as?: Component;
		/** Common router destination prop, available with the default anchor type. */
		to?: string;
	};

export function FoglampLink<Component extends FoglampLinkComponent = "a">({
	component,
	as,
	...props
}: FoglampLinkProps<Component>) {
	const providerComponent = React.useContext(FoglampLinkContext);
	const LinkComponent = component ?? as ?? providerComponent;

	return React.createElement(LinkComponent, props as React.ComponentPropsWithRef<Component>);
}

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/packages/ui/src/lib/utils.ts; derived here under Apache-2.0.
 */
export { cn } from "cn";

/**
 * Original UI & design: Gustavo Fior (@gustavo-fior), Abdul Haidar & Foglamp Labs.
 * Extracted from https://github.com/foglamp-labs/foglamp — Apache-2.0.
 */
"use client";

import { IconTool } from "@tabler/icons-react";
import type { FoggyMessageData } from "./types";
import { Streamdown } from "streamdown";

import { cn } from "../../lib/utils";

import { markdownComponents } from "./markdown";

// A subtle pill shown while a tool call is in flight or done, so the user can
// see Foggy reaching into their data.
function ToolChip({ label, done }: { label: string; done: boolean }) {
  return (
    <div className="flex w-fit items-center gap-1.5 ml-3 py-1 text-xs text-muted-foreground">
      <IconTool
        className={cn(
          "size-3 shrink-0 fill-current stroke-0",
          !done && "animate-pulse"
        )}
      />
      {done ? "Looked up" : "Looking up"} {label}
    </div>
  );
}

// Turn `tool-listTraces` / `dynamic-tool` into a human label.
function toolLabel(type: string, part: Record<string, unknown>): string {
  const name =
    type === "dynamic-tool"
      ? String(part.toolName ?? "data")
      : type.replace(/^tool-/, "");
  return name.replace(/([a-z])([A-Z])/g, "$1 $2").toLowerCase();
}

export function FoggyMessage({ message }: { message: FoggyMessageData }) {
  const isUser = message.role === "user";

  return (
    <div
      className={cn(
        "flex flex-col gap-1.5",
        isUser ? "items-end" : "items-start"
      )}
    >
      {message.parts.map((part, i) => {
        const key = `${message.id}-${i}`;

        if (part.type === "text") {
          if (!part.text) return null;
          return isUser ? (
            <div
              key={key}
              className="max-w-[85%] whitespace-pre-wrap rounded-lg squircle:rounded-3xl corner-squircle bg-card shadow-(--custom-shadow)  px-3 py-2 text-sm text-primary"
            >
              {part.text}
            </div>
          ) : (
            <div
              key={key}
              className="max-w-[90%] px-3 py-0 text-sm leading-relaxed [&_li]:my-0.5 [&_ol]:my-1.5 [&_ol]:list-decimal [&_ol]:pl-5 [&_p]:my-1.5 [&_pre]:my-2 [&_ul]:my-1.5 [&_ul]:list-disc [&_ul]:pl-5 *:first:mt-0 *:last:mb-0"
            >
              <Streamdown
                components={markdownComponents}
                controls={{ table: false }}
              >
                {part.text}
              </Streamdown>
            </div>
          );
        }

        if (part.type === "dynamic-tool" || part.type.startsWith("tool-")) {
          const p = part;
          const done =
            p.state === "output-available" || p.state === "output-error";
          return (
            <ToolChip key={key} label={toolLabel(part.type, p)} done={done} />
          );
        }

        return null;
      })}
    </div>
  );
}

/**
 * Original UI & design: Gustavo Fior (@gustavo-fior), Abdul Haidar & Foglamp Labs.
 * Extracted from https://github.com/foglamp-labs/foglamp — Apache-2.0.
 */
import type { ComponentProps } from "react";
import { FoglampLink as Link } from "../../lib/link-context";

// Shared Streamdown component overrides for rendering model markdown across the
// app (Foggy chat, session transcripts, …). Pass as `components` to <Streamdown>.
export const markdownComponents = {
	// Route relative links through the host link provider for in-app nav;
	// open absolute links (docs, external) in a new tab.
	a: ({ href = "", children, ...rest }: ComponentProps<"a">) => {
		if (href.startsWith("/")) {
			return (
				<Link
					href={href}
					className="font-medium text-primary underline underline-offset-2"
				>
					{children}
				</Link>
			);
		}
		return (
			<a
				{...rest}
				href={href}
				target="_blank"
				rel="noreferrer"
				className="font-medium text-primary underline underline-offset-2"
			>
				{children}
			</a>
		);
	},
	// Flat, chat-native tables — replaces Streamdown's bordered card + toolbar.
	// The wrapper scrolls horizontally so wide tables never break the layout.
	table: ({ children }: ComponentProps<"table">) => (
		<div className="my-3 w-full overflow-x-auto rounded-md squircle:rounded-xl corner-squircle border border-border/60">
			<table className="w-full border-collapse text-xs tabular-nums">
				{children}
			</table>
		</div>
	),
	thead: ({ children }: ComponentProps<"thead">) => (
		<thead className="bg-muted/40 text-muted-foreground">{children}</thead>
	),
	tr: ({ children }: ComponentProps<"tr">) => (
		<tr className="border-b border-border/40 last:border-0">{children}</tr>
	),
	th: ({ children }: ComponentProps<"th">) => (
		<th className="px-3 py-2 text-left font-medium whitespace-nowrap">
			{children}
		</th>
	),
	td: ({ children }: ComponentProps<"td">) => (
		<td className="px-3 py-1.5 align-top">{children}</td>
	),
	// Streamdown wraps images in a <div> for its hover controls, but markdown puts
	// images inside paragraphs — a <div> inside a <p> is invalid HTML, and React
	// throws a hydration error on it. A bare <img> is valid wherever an image can
	// legally appear, so it renders the same in every context.
	img: ({ src, alt, ...rest }: ComponentProps<"img">) => (
		// These are arbitrary remote URLs from model
		// output, not assets the optimizer can be pointed at.
		<img
			{...rest}
			src={typeof src === "string" ? src : undefined}
			alt={alt ?? ""}
			className="my-1.5 inline-block max-h-64 max-w-full rounded-md"
		/>
	),
	hr: () => <hr className="my-3 border-border/60" />,
};

/**
 * Original UI & design: Gustavo Fior (@gustavo-fior), Abdul Haidar & Foglamp Labs.
 * Extracted from https://github.com/foglamp-labs/foglamp — Apache-2.0.
 */
export type FoggyMessagePart =
  | { type: "text"; text: string }
  | { type: `tool-${string}` | "dynamic-tool"; toolName?: string; state: string };
export interface FoggyMessageData {
  id: string;
  role: "user" | "assistant" | "system";
  parts: FoggyMessagePart[];
}
